"""Independent curved mesh topology, actual quadratic loads and release separation."""
from pathlib import Path
from datetime import datetime
from zoneinfo import ZoneInfo
import argparse,hashlib,json,time
import numpy as np
from scipy import sparse
from scipy.sparse.csgraph import connected_components
from geobc.copv_quadratic_boundary import native_boundary_loads
from geobc.copv_structured_mesh import analytic_segments
W=Path(__file__).resolve().parents[1]
def read(p):return json.loads(p.read_text(encoding='utf-8'))
def write(p,d):p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
def main():
    ap=argparse.ArgumentParser();ap.add_argument('root',type=Path);args=ap.parse_args();root=args.root.resolve();out=root/'preflight';out.mkdir(exist_ok=False);start=time.perf_counter();result=read(root/'result.json');assert result['status']=='curved_positive_J_mesh_preflight_only';geometry=read(root/'geometry_check/review.json');meshhash=hashlib.sha256((root/'mesh/mesh.npz').read_bytes()).hexdigest();assert geometry['mesh_sha256']==meshhash;geometry_pass=bool(geometry['passed'] and not (root/'local_geometry_hold.json').exists());resource_policy_path=W/'data/copv/c04_repair_v3/resource_amendment_v1.json';resource_policy=read(resource_policy_path);m=np.load(root/'mesh/mesh.npz');xyz=m['xyz'];cells=m['cells'];pids=m['cell_part_ids'];review=read(root/'mesh/mesh_review.json');assert np.isfinite(xyz).all() and np.isfinite(m['min_det_jac']).all() and m['min_det_jac'].min()>0
    local=np.array([[1,2,3,5,8,9],[0,3,2,7,8,6],[0,1,3,4,9,7],[0,2,1,6,5,4]]);faces=cells[:,local].reshape(-1,6);owners=np.repeat(np.arange(len(cells)),4);key=np.ascontiguousarray(np.sort(faces[:,:3],axis=1)).view(np.dtype((np.void,24))).ravel();order=np.argsort(key);sortedkey=key[order];starts=np.r_[0,np.flatnonzero(sortedkey[1:]!=sortedkey[:-1])+1];counts=np.diff(np.r_[starts,len(order)]);assert counts.max()<=2
    exterior=order[starts[counts==1]];shared=starts[counts==2];a=order[shared];b=order[shared+1];assert np.array_equal(np.sort(faces[a],axis=1),np.sort(faces[b],axis=1)),'Nonconformal midside interface';different=pids[owners[a]]!=pids[owners[b]];interface=np.r_[a[different],b[different]];selection=np.r_[exterior,interface];sf=out/'surface.npz';np.savez_compressed(sf,faces=faces[selection],owner_cells=owners[selection],part_ids=pids[owners[selection]],is_exterior=np.r_[np.ones(len(exterior),bool),np.zeros(len(interface),bool)])
    extfaces=faces[exterior];extowners=owners[exterior];del faces,owners,key,order,sortedkey,starts,counts,a,b,shared,selection
    corners=np.unique(cells[:,:4]);inv=np.full(len(xyz),-1,np.int64);inv[corners]=np.arange(len(corners));edges=np.concatenate([cells[:,[i,j]] for i,j in [(0,1),(0,2),(0,3),(1,2),(1,3),(2,3)]]);graph=sparse.coo_matrix((np.ones(len(edges)),(inv[edges[:,0]],inv[edges[:,1]])),shape=(len(corners),len(corners)));components,_=connected_components(graph,directed=False);assert components==1;del graph,edges,inv
    params=review['parameters_mm'];rz,_=analytic_segments(params,(4,2500,16,2500,4));loads,tags,closure=native_boundary_loads(xyz,cells,extfaces,extowners,params,rz);write(out/'quadratic_load_closure.json',closure)
    np.savez_compressed(out/'native_boundary_vectors.npz',node_ids=m['node_ids'],pressure_load_N=loads[0],upper_cap_load_N=loads[1],lower_cap_load_N=loads[2],consistent_load_N=sum(loads))
    volume_pass=result['max_part_volume_error']<=.001;resource_pass=len(cells)<=resource_policy['max_cells'] and 3*len(xyz)<=resource_policy['max_P2_DOFs'];shape_pass=result['stages'][-1]['min_SICN']>=.05
    validation_allowed=bool(volume_pass and geometry_pass and resource_pass and closure['passed'])
    record=dict(schema='c04_curved_mesh_preflight_v2',created=datetime.now(ZoneInfo('Asia/Shanghai')).isoformat(),case_id=result['case_id'],mesh_sha256=meshhash,native_vectors_sha256=hashlib.sha256((out/'native_boundary_vectors.npz').read_bytes()).hexdigest(),closure_sha256=hashlib.sha256((out/'quadratic_load_closure.json').read_bytes()).hexdigest(),topology_passed=True,shared_Tri6_interfaces=True,connected_components=int(components),positive_Jacobians=True,max_material_volume_error=result['max_part_volume_error'],material_volume_passed=volume_pass,resource_guard_passed=resource_pass,resource_policy_file=str(resource_policy_path.relative_to(W)),resource_policy_sha256=hashlib.sha256(resource_policy_path.read_bytes()).hexdigest(),local_geometry_screen_passed=geometry_pass,local_geometry_review_sha256=hashlib.sha256((root/'geometry_check/review.json').read_bytes()).hexdigest(),quadratic_load_closure_passed=closure['passed'],original_volume_SICN_target_passed=shape_pass,original_surface_SICN_target_passed=geometry['min_surface_SICN']>=.05,original_mesh_release_passed=False,candidate_FE_validation_allowed=validation_allowed,production_eligible=False,scope='Repair candidate verification only after actual local CAD, volume, topology, load and resource screens. Original SICN target and production hold are unchanged; no stress-convergence certification.',seconds=time.perf_counter()-start)
    write(out/'review.json',record);review.update(connected_components=int(components),curved_preflight=record,C04_production_gate=dict(passed=False,status='candidate_validation_only_original_shape_target_unresolved'));write(root/'mesh/mesh_review_curved_checked.json',review);print(json.dumps(record),flush=True)
if __name__=='__main__':main()
